import React, { useState, useCallback, useMemo } from 'react';
import { Search, Plus, ChevronRight, ChevronDown, Users, User, X, Send, CheckSquare, Calendar } from 'lucide-react';

// Mock data - aynı kalıyor
const initialData = {
  ideas: [
    {
      id: 1,
      title: "E-Ticaret Mobil Uygulaması",
      description: "Kullanıcı dostu arayüzü olan modern bir e-ticaret uygulaması geliştirmek",
      category: "Teknoloji",
      status: "Devam Ediyor",
      priority: "Yüksek",
      tags: ["mobil", "e-ticaret", "react-native"],
      assignedTo: ["Ahmet Y.", "Zeynep K."],
      progress: 65,
      tasks: [
        {
          id: 101,
          title: "UI/UX Tasarım",
          description: "Ana sayfa ve ürün sayfası tasarımları",
          status: "Tamamlandı",
          priority: "Yüksek",
          assignedTo: "Zeynep K.",
          dueDate: "2024-01-25",
          comments: [
            { id: 1, author: "Zeynep K.", text: "Mockup'lar hazırlandı", date: "2024-01-22" }
          ],
          checklist: [
            { id: 1, text: "Ana sayfa wireframe", completed: true },
            { id: 2, text: "Sepet sayfası", completed: false }
          ]
        }
      ]
    }
  ]
};

function App() {
  // States
  const [ideas, setIdeas] = useState(initialData.ideas);
  const [expandedIdeas, setExpandedIdeas] = useState({});
  const [selectedTask, setSelectedTask] = useState(null);
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  
  // Drag & Drop
  const [draggedIdea, setDraggedIdea] = useState(null);
  const [dragOverIndex, setDragOverIndex] = useState(null);

  // Filtrelenmiş fikirler
  const filteredIdeas = useMemo(() => {
    return ideas.filter(idea => 
      idea.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      idea.description.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [ideas, searchTerm]);

  // Görev güncelleme
  const updateTask = useCallback((taskId, updatedTask) => {
    setIdeas(prev => prev.map(idea => ({
      ...idea,
      tasks: idea.tasks.map(task => 
        task.id === taskId ? { ...task, ...updatedTask } : task
      )
    })));
    
    if (selectedTask?.id === taskId) {
      setSelectedTask(prev => ({ ...prev, ...updatedTask }));
    }
  }, [selectedTask]);

  // Drag handlers
  const handleDragStart = (e, idea, index) => {
    setDraggedIdea({ idea, originalIndex: index });
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    setDraggedIdea(null);
    setDragOverIndex(null);
  };

  const handleDragOver = (e, index) => {
    e.preventDefault();
    setDragOverIndex(index);
  };

  const handleDrop = (e, dropIndex) => {
    e.preventDefault();
    if (!draggedIdea || draggedIdea.originalIndex === dropIndex) return;

    const newIdeas = [...ideas];
    const draggedData = filteredIdeas[draggedIdea.originalIndex];
    const targetData = filteredIdeas[dropIndex];
    
    const draggedIndex = newIdeas.findIndex(i => i.id === draggedData.id);
    const targetIndex = newIdeas.findIndex(i => i.id === targetData.id);
    
    [newIdeas[draggedIndex], newIdeas[targetIndex]] = [newIdeas[targetIndex], newIdeas[draggedIndex]];
    
    setIdeas(newIdeas);
    setDragOverIndex(null);
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: 'system-ui, -apple-system, sans-serif'
    }}>
      <style>{`
        .idea-card {
          background: rgba(255,255,255,0.1);
          border: 1px solid rgba(255,255,255,0.1);
          border-radius: 16px;
          padding: 24px;
          margin: 20px 0;
          cursor: move;
          transition: all 0.3s ease;
        }
        .idea-card:hover {
          transform: translateY(-2px);
          box-shadow: 0 8px 32px rgba(0,0,0,0.12);
        }
        .drag-over {
          border-color: #4caf50;
          box-shadow: 0 0 20px rgba(76,175,80,0.3);
        }
      `}</style>

      {/* Header */}
      <div style={{ padding: '20px', background: 'rgba(255,255,255,0.1)', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
        <div style={{ maxWidth: '1200px', margin: '0 auto', display: 'flex', gap: '20px', alignItems: 'center' }}>
          <h1 style={{ color: 'white', margin: 0 }}>idetree</h1>
          <div style={{ position: 'relative', flex: 1, maxWidth: '400px' }}>
            <Search size={20} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'rgba(255,255,255,0.6)' }} />
            <input
              type="text"
              placeholder="Fikirlerinizde arayın..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{
                width: '100%',
                padding: '12px 12px 12px 40px',
                border: '1px solid rgba(255,255,255,0.1)',
                borderRadius: '12px',
                background: 'rgba(255,255,255,0.1)',
                color: 'white',
                fontSize: '14px'
              }}
            />
          </div>
        </div>
      </div>

      {/* Ana İçerik */}
      <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '30px' }}>
        {filteredIdeas.map((idea, index) => (
          <div key={idea.id} style={{ position: 'relative' }}>
            {dragOverIndex === index && (
              <div style={{
                position: 'absolute',
                top: '-4px',
                left: 0,
                right: 0,
                height: '4px',
                background: '#4caf50',
                borderRadius: '2px'
              }} />
            )}
            
            <div
              className={`idea-card ${dragOverIndex === index ? 'drag-over' : ''}`}
              draggable
              onDragStart={(e) => handleDragStart(e, idea, index)}
              onDragEnd={handleDragEnd}
              onDragOver={(e) => handleDragOver(e, index)}
              onDrop={(e) => handleDrop(e, index)}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start', marginBottom: '16px' }}>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', marginBottom: '8px' }}>
                    <button
                      onClick={() => setExpandedIdeas(prev => ({ ...prev, [idea.id]: !prev[idea.id] }))}
                      style={{
                        background: 'none',
                        border: 'none',
                        color: 'white',
                        cursor: 'pointer',
                        padding: '4px',
                        display: 'flex',
                        alignItems: 'center'
                      }}
                    >
                      {expandedIdeas[idea.id] ? <ChevronDown size={20} /> : <ChevronRight size={20} />}
                    </button>
                    <h3 style={{ color: 'white', fontSize: '20px', margin: '0 0 0 8px' }}>{idea.title}</h3>
                  </div>
                  <p style={{ color: 'rgba(255,255,255,0.8)', marginBottom: '12px' }}>
                    {idea.description}
                  </p>
                  
                  <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
                    <span style={{
                      background: 'rgba(255,255,255,0.1)',
                      padding: '4px 12px',
                      borderRadius: '20px',
                      fontSize: '12px',
                      color: 'white'
                    }}>
                      {idea.category}
                    </span>
                    <span style={{
                      background: 'rgba(255,255,255,0.1)',
                      padding: '4px 12px',
                      borderRadius: '20px',
                      fontSize: '12px',
                      color: 'white'
                    }}>
                      {idea.status}
                    </span>
                  </div>
                </div>
              </div>

              {expandedIdeas[idea.id] && (
                <div style={{ marginTop: '20px' }}>
                  <h4 style={{ color: '#64b5f6', marginBottom: '12px' }}>Görevler ({idea.tasks.length})</h4>
                  {idea.tasks.map(task => (
                    <div
                      key={task.id}
                      onClick={() => { setSelectedTask(task); setIsTaskModalOpen(true); }}
                      style={{
                        background: 'rgba(255,255,255,0.08)',
                        border: '1px solid rgba(255,255,255,0.1)',
                        borderRadius: '12px',
                        padding: '14px 18px',
                        margin: '8px 0',
                        cursor: 'pointer',
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center'
                      }}
                    >
                      <div>
                        <div style={{ fontWeight: '500', color: 'white', marginBottom: '4px' }}>{task.title}</div>
                        <div style={{ fontSize: '12px', color: 'rgba(255,255,255,0.7)' }}>
                          {task.status} • {task.assignedTo}
                        </div>
                      </div>
                      <ChevronRight size={16} style={{ color: 'rgba(255,255,255,0.5)' }} />
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Task Modal */}
      {isTaskModalOpen && selectedTask && (
        <TaskModal task={selectedTask} onClose={() => setIsTaskModalOpen(false)} onUpdateTask={updateTask} />
      )}
    </div>
  );
}

// Task Modal Component
function TaskModal({ task, onClose, onUpdateTask }) {
  const [activeTab, setActiveTab] = useState('checklist');
  const [newChecklistItem, setNewChecklistItem] = useState('');

  const addChecklistItem = () => {
    if (!newChecklistItem.trim()) return;
    
    const newItem = {
      id: Date.now(),
      text: newChecklistItem.trim(),
      completed: false
    };
    const updatedChecklist = [...(task.checklist || []), newItem];
    onUpdateTask(task.id, { checklist: updatedChecklist });
    setNewChecklistItem('');
  };

  const toggleChecklistItem = (itemId) => {
    const updatedChecklist = task.checklist.map(item =>
      item.id === itemId ? { ...item, completed: !item.completed } : item
    );
    onUpdateTask(task.id, { checklist: updatedChecklist });
  };

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0,0,0,0.7)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 1000
    }}>
      <div style={{
        background: 'white',
        borderRadius: '20px',
        width: '90%',
        maxWidth: '600px',
        maxHeight: '80vh',
        overflow: 'hidden'
      }}>
        <div style={{
          background: 'linear-gradient(135deg, #667eea, #764ba2)',
          color: 'white',
          padding: '20px 30px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}>
          <h2>{task.title}</h2>
          <button
            onClick={onClose}
            style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer', fontSize: '24px' }}
          >
            <X size={24} />
          </button>
        </div>
        
        <div style={{ padding: '30px' }}>
          <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
            <button
              onClick={() => setActiveTab('checklist')}
              style={{
                padding: '10px 20px',
                border: 'none',
                background: activeTab === 'checklist' ? '#667eea' : 'transparent',
                color: activeTab === 'checklist' ? 'white' : '#666',
                borderRadius: '8px',
                cursor: 'pointer'
              }}
            >
              Checklist ({task.checklist?.length || 0})
            </button>
          </div>

          {activeTab === 'checklist' && (
            <div>
              <div style={{ marginBottom: '20px' }}>
                {task.checklist?.map(item => (
                  <div key={item.id} style={{
                    display: 'flex',
                    alignItems: 'center',
                    padding: '12px',
                    background: item.completed ? '#f0f8f0' : '#f8f9fa',
                    borderRadius: '8px',
                    marginBottom: '8px',
                    border: `1px solid ${item.completed ? '#4caf50' : '#e1e5e9'}`
                  }}>
                    <input
                      type="checkbox"
                      checked={item.completed}
                      onChange={() => toggleChecklistItem(item.id)}
                      style={{ marginRight: '12px', transform: 'scale(1.2)', cursor: 'pointer' }}
                    />
                    <span style={{
                      color: item.completed ? '#4caf50' : '#333',
                      textDecoration: item.completed ? 'line-through' : 'none',
                      flex: 1
                    }}>
                      {item.text}
                    </span>
                  </div>
                ))}
              </div>
              
              <div style={{ display: 'flex', gap: '12px' }}>
                <input
                  type="text"
                  placeholder="Yeni öğe ekle..."
                  value={newChecklistItem}
                  onChange={(e) => setNewChecklistItem(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && addChecklistItem()}
                  style={{
                    flex: 1,
                    padding: '10px 12px',
                    border: '2px solid #e1e5e9',
                    borderRadius: '8px'
                  }}
                />
                <button
                  onClick={addChecklistItem}
                  disabled={!newChecklistItem.trim()}
                  style={{
                    background: newChecklistItem.trim() ? '#4caf50' : '#ccc',
                    color: 'white',
                    border: 'none',
                    padding: '10px 16px',
                    borderRadius: '8px',
                    cursor: newChecklistItem.trim() ? 'pointer' : 'not-allowed'
                  }}
                >
                  Ekle
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
